{
  "version": "2b1",
  "blocks": [
    {
      "type": "text",
      "text": "BYOK means “Bring Your Own Key.” In a model-powered app, it usually means you supply an API key from your own model provider account. The app uses that key to make model requests, so usage typically counts toward your provider account’s billing and rate limits. BYOK does not necessarily mean prompts bypass the app’s servers; that depends on how the app is built."
    }
  ]
}

